CREATE OR REPLACE FUNCTION public.customer_report_attention(_mode text, _hours numeric, _last date, _next timestamptz, _visits bigint, _day date) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE _mode WHEN 'renewal-opportunities' THEN public.customer_report_preset('low-hours',NULL,_last,_next,_visits,_hours,NULL,NULL,_day) AND (_next IS NOT NULL OR _last IS NOT NULL) WHEN 'inactive-repeat' THEN _visits>=2 AND public.customer_report_preset('inactive',NULL,_last,_next,_visits,_hours,NULL,NULL,_day) ELSE true END $$;
REVOKE ALL ON FUNCTION public.customer_report_attention(text,numeric,date,timestamptz,bigint,date) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.customer_report_attention(text,numeric,date,timestamptz,bigint,date) TO service_role;
DO $patch$
DECLARE definition text;
BEGIN
 SELECT pg_get_functiondef('public.customer_report(text,text,text,date,date,text,text,text,uuid,integer,integer,timestamptz)'::regprocedure) INTO definition;
 IF strpos(definition,$old$'low-hours','online'$old$)=0 OR strpos(definition,'bs.first_visit,bs.last_visit,bs.next_booking')=0 OR strpos(definition,'), filtered AS (SELECT * FROM customer_rows WHERE')=0 THEN RAISE EXCEPTION 'Unexpected customer report definition'; END IF;
 definition:=replace(definition,$old$'low-hours','online'$old$,$new$'low-hours','online','dashboard','renewal-opportunities','inactive-repeat'$new$);
 definition:=replace(definition,'SELECT profile_id,min(visit_day) FILTER(WHERE qualifies)', $new$SELECT profile_id,min(start_time) FILTER(WHERE status='confirmed' AND start_time>v_as_of) AS next_confirmed,min(visit_day) FILTER(WHERE qualifies)$new$);
 definition:=replace(definition,'bs.first_visit,bs.last_visit,bs.next_booking',$new$bs.first_visit,bs.last_visit,CASE WHEN _preset IN ('dashboard','renewal-opportunities','inactive-repeat') THEN bs.next_confirmed ELSE bs.next_booking END AS next_booking$new$);
 definition:=replace(definition,$old$), filtered AS (SELECT * FROM customer_rows WHERE _type='all' OR customer_status=_type), page AS (SELECT * FROM filtered ORDER BY lower(coalesce(display_name,'')),id OFFSET _offset LIMIT _limit)$old$, $new$), filtered AS (SELECT * FROM customer_rows WHERE (_type='all' OR customer_status=_type) AND public.customer_report_attention(_preset,CASE WHEN member_hours_id IS NOT NULL THEN hours_remaining END,(last_visit AT TIME ZONE 'Asia/Kolkata')::date,next_booking,lifetime_visits,v_day)),
 renewal_candidates AS (SELECT id,display_name,email,hours_remaining,next_booking,last_visit,lifetime_visits FROM filtered WHERE _preset='dashboard' AND public.customer_report_attention('renewal-opportunities',CASE WHEN member_hours_id IS NOT NULL THEN hours_remaining END,(last_visit AT TIME ZONE 'Asia/Kolkata')::date,next_booking,lifetime_visits,v_day)),
 renewal_page AS (SELECT * FROM renewal_candidates ORDER BY next_booking ASC NULLS LAST,last_visit DESC NULLS LAST,id LIMIT 5),
 inactive_candidates AS (SELECT id,display_name,email,hours_remaining,next_booking,last_visit,lifetime_visits FROM filtered WHERE _preset='dashboard' AND public.customer_report_attention('inactive-repeat',NULL,(last_visit AT TIME ZONE 'Asia/Kolkata')::date,next_booking,lifetime_visits,v_day)),
 inactive_page AS (SELECT * FROM inactive_candidates ORDER BY last_visit DESC,id LIMIT 5),
 upcoming AS (SELECT b.* FROM public.bookings b WHERE _preset='dashboard' AND b.city=ANY(v_cities) AND b.status='confirmed' AND b.start_time>=v_as_of ORDER BY b.start_time,b.id LIMIT 5),
 first_arrivals AS (SELECT u.id FROM upcoming u JOIN booking_owners o ON o.id=u.id WHERE NOT EXISTS(SELECT 1 FROM scoped_bookings previous WHERE previous.profile_id=o.profile_id AND previous.city=u.city AND previous.qualifies AND previous.start_time<u.start_time AND previous.visit_id<>coalesce(u.parent_booking_id,u.id))),
 page AS (SELECT * FROM filtered ORDER BY CASE WHEN _preset='renewal-opportunities' THEN next_booking END ASC NULLS LAST, CASE WHEN _preset IN ('renewal-opportunities','inactive-repeat') THEN last_visit END DESC NULLS LAST,lower(coalesce(display_name,'')),id OFFSET _offset LIMIT _limit)$new$);
 definition:=replace(definition,$old$'rows',coalesce((SELECT jsonb_agg(to_jsonb(page)) FROM page)$old$, $new$'renewals',coalesce((SELECT jsonb_agg(to_jsonb(renewal_page)) FROM renewal_page),'[]'::jsonb),'inactive',coalesce((SELECT jsonb_agg(to_jsonb(inactive_page)) FROM inactive_page),'[]'::jsonb),'renewal_total',(SELECT count(*) FROM renewal_candidates),'inactive_total',(SELECT count(*) FROM inactive_candidates),'first_visits',coalesce((SELECT jsonb_agg(id) FROM first_arrivals),'[]'::jsonb),'rows',coalesce((SELECT jsonb_agg(to_jsonb(page)) FROM page)$new$);
 IF strpos(definition,'renewal_candidates AS')=0 OR strpos(definition,'AS next_confirmed')=0 THEN RAISE EXCEPTION 'Dashboard extension failed'; END IF;
 EXECUTE definition;
END $patch$;
COMMENT ON FUNCTION public.customer_report_attention(text,numeric,date,timestamptz,bigint,date) IS 'Read-only dashboard eligibility: existing one-hour renewal threshold with activity evidence; two lifetime qualifying visits and 60-day inactivity without future confirmed bookings.';